// What the OTA runtime version hashes (docs/OTA.md). Left out: package.json scripts (tool scripts like replay:* never
// reach the native build), .gitignore (ios/ and android/ are generated by prebuild, never committed), and app.config's
// `extra`: native code never reads it, and a JS update carries its own (the manifest's `extra.expoClient`), so a new
// support address or Sentry DSN goes out as an update instead of orphaning every installed build (2026-10-14: a support
// email alone made a new runtime). Except the distribution: store and sideloaded builds must never share a runtime,
// or one's updates (AltStore, the APK installer, trip upload) would reach the other. Anything else native, from
// app.json to patches/, still makes a new runtime that needs a new IPA/APK.
/** @type {import('expo/fingerprint').Config} */
const config = {
  sourceSkips: ["PackageJsonScriptsAll", "GitIgnore", "ExpoConfigExtraSection"],
  extraSources: [
    {
      type: "contents",
      id: "distribution",
      contents: process.env.DISTRIBUTION?.trim() === "store" ? "store" : "sideload",
      reasons: ["DISTRIBUTION (app.config.js extra.distribution)"],
    },
  ],
};

module.exports = config;
